addHook.description:
DIV{HEADER1{addHook,  -- add a hook function to an object for later processing}, UL{LI{DL{class => element, DT{Usage: }, DD{CODE{addHook(key, hook), class => language-macaulay2}}, DD{CODE{addHook(store, key, hook), class => language-macaulay2}}}}, LI{Inputs:, UL{LI{SPAN{TT{key}, , , SPAN{a , TO2{Macaulay2Doc :: Sequence, sequence}},  or , SPAN{a , TO2{Macaulay2Doc :: Symbol, symbol}}, , }}, LI{SPAN{TT{hook}, , , SPAN{a , TO2{Macaulay2Doc :: Function, function}}, , }}, LI{SPAN{TT{store}, , , SPAN{a , TO2{Macaulay2Doc :: MutableHashTable, mutable hash table}}, , }}}}, LI{TO2{Macaulay2Doc :: using functions with optional inputs, Optional inputs}, :, UL{LI{SPAN{TT{Strategy}, TT{ => }, SPAN{a , TO2{Macaulay2Doc :: Thing, thing}}, , , SPAN{default value , null}, , , TEX{specifies the name for the hook}}}}}, LI{DIV{Consequences:, UL{LI{TEX{the function }, TT{hook}, TEX{ is added to the (possibly absent) hash table of hooks, which is either stored in the mutable hash table }, TT{store}, TEX{ or under the }, TO{Macaulay2Doc :: youngest}, TEX{ }, TO{Macaulay2Doc :: Type}, TEX{ }, TT{T}, TEX{ listed in the }, TO{Macaulay2Doc :: method}, TEX{ key }, TT{key}, TEX{. In the latter case, the hash table is either stored in }, TT{T.Hooks#key}, TEX{ if }, TT{T}, TEX{ is mutable, or in }, TT{T.cache.Hooks#key}, TEX{ otherwise. If no appropriate object is found, or if }, TT{key}, TEX{ is a }, TO{Macaulay2Doc :: Symbol}, TEX{, then the hook is stored under the hash table }, TT{GlobalHookStore}}}}}}, DIV{HEADER2{Description}, DIV{PARA{TEX{For an explanation and examples of hooks see }, TO{Macaulay2Doc :: using hooks}, TEX{.}}}}, DIV{class => waystouse, DIV{HEADER2{Code}, PRE{CODE{../../m2/methods.m2:626:46-636:36: --source code:
addHook(MutableHashTable, Thing, Function) := opts -> (store, key, hook) -> (
    -- this is the hashtable of Hooks for a specific key, which stores HookAlgorithms and HookPriority
    store#key ??= new MutableHashTable from {
        HookAlgorithms => new MutableHashTable, -- a mutable hash table "strategy key" => "strategy code"
        HookPriority   => new MutableList};     -- a mutable list of strategy keys, in order
    store = store#key;
    ind := #store.HookPriority; -- index to add the hook in the list; TODO: use Priority to insert in the middle?
    alg := if opts.Strategy =!= null then opts.Strategy else ind;
