cite.description:
DIV{HEADER1{cite,  -- obtain bibtex citations for Macaulay2 packages}, UL{LI{DL{class => element, DT{Usage: }, DD{CODE{cite, class => language-macaulay2}}, DD{CODE{cite P, class => language-macaulay2}}, DD{CODE{cite S, class => language-macaulay2}}}}, LI{Inputs:, UL{LI{SPAN{TT{P}, , , SPAN{a , TO2{Macaulay2Doc :: Package, package}}, , }}, LI{SPAN{TT{S}, , , SPAN{a , TO2{Macaulay2Doc :: String, string}}, , }}}}, LI{Outputs:, UL{LI{SPAN{TT{T}, , , SPAN{a , TO2{Macaulay2Doc :: String, string}}, , , TEX{bibtex entry or entries}}}}}}, DIV{HEADER2{Description}, DIV{PARA{TEX{When called without an argument, }, TO{PackageCitations :: cite}, TEX{ produces the desired reference to Macaulay2.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i1 : cite

o1 = @misc{M2,
       author = {Grayson, Daniel R. and Stillman, Michael E.},
       title = {Macaulay2, a software system for research in algebraic geometry},
       howpublished = {Available at \url{https://macaulay2.com/}}
     }, class => language-macaulay2}}}}}, DIV{PARA{TEX{When applied to a loaded package }, TO{PackageCitations :: cite}, TEX{ returns a bibtex citation for inclusion in a LaTeX document, assuming there is enough information included in the package to build it. Compare the following.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i2 : cite PackageCitations

o2 = @misc{PackageCitationsSource,
       title = {{PackageCitations: citation of \emph{Macaulay2} packages. Version~0.1}},
       author = {Aaron Dall},
       howpublished = {A \emph{Macaulay2} package available at
         "https://github.com/aarondall/PackageCitations-M2"}
     }, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i3 : cite Text
Warning: The "Text" package provides insufficient citation data: author.

o3 = @misc{TextSource,
       title = {{Text: documentation and hypertext. Version~0.0}},
       author = {},
       howpublished = {A \emph{Macaulay2} package available at
         \url{https://github.com/Macaulay2/M2/tree/stable/M2/Macaulay2/packages}}
     }, class => language-macaulay2}}}}}, DIV{PARA{TEX{If }, TO{PackageCitations :: cite}, TEX{ is given a string, then it will load the package if necessary and issue the corresponding citation. Note that if the package is }, TO2{Macaulay2Doc :: Certification, certified}, TEX{ then two bibtex entries will be produced: one for the article witnessing the certification and one for the source code. Moreover, if the headline of a package does not meet a certain set of criteria then a more generic title containing  "A Macaulay2 package" is produced. For example, the package PieriMaps is a certified Macaulay2 package whose headline is deemed too long by the }, TO{PackageCitations :: cite}, TEX{ method.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i4 : cite "PieriMaps"

o4 = @misc{PieriMapsSource,
       title = {{PieriMaps: A \emph{Macaulay2} package. Version~1.0}},
       author = {Steven V Sam},
       howpublished = {A \emph{Macaulay2} package available at
         \url{https://github.com/Macaulay2/M2/tree/stable/M2/Macaulay2/packages}}
     }

     @article{PieriMapsArticle,
       title = {{Computing inclusions of Schur modules}},
       author = {Steven V Sam},
       journal = {The Journal of Software for Algebra and Geometry: Macaulay2},
       volume = {1},
       year = {2009},
     }, class => language-macaulay2}}}}}, DIV{PARA{TEX{No effort is made to correct apparent typos in the package data. The user is urged to check for correct spelling and grammar.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i5 : cite "Bruns"

o5 = @misc{BrunsSource,
       title = {{Bruns: make a 3-generator ideal with an ``any" resolution. Version~2.0}},
       author = {David Eisenbud},
       howpublished = {A \emph{Macaulay2} package available at
         \url{https://github.com/Macaulay2/M2/tree/stable/M2/Macaulay2/packages}}
     }, class => language-macaulay2}}}}}}, DIV{HEADER2{See also}, UL{LI{TOH{PackageCitations :: PackageCitations}}}}, DIV{DIV{class => waystouse, HEADER2{For the programmer}, PARA{The object , TO{PackageCitations :: cite},  is , SPAN{a , TO2{Macaulay2Doc :: Command, command}}, .}}, HR{}, DIV{class => waystouse, PARA{The source of this document is in , TT{PackageCitations.m2:316:0}, .}}}}

