o7 = MutableList{...5...}

o7 : MutableList, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i8 : deepSplice M

o8 = MutableList{...10...}

o8 : MutableList, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i9 : M

o9 = MutableList{...5...}

o9 : MutableList, class => language-macaulay2}}}}}}, DIV{HEADER2{See also}, UL{LI{TOH{Macaulay2Doc :: flatten}}, LI{TOH{Macaulay2Doc :: splice}}, LI{TOH{Macaulay2Doc :: lists and sequences}}}}, DIV{DIV{class => waystouse, HEADER2{Ways to use , TT{deepSplice}, :}, UL{LI{KBD{deepSplice(BasicList)}}}}, DIV{class => waystouse, HEADER2{For the programmer}, PARA{The object , TO{Macaulay2Doc :: deepSplice},  is , SPAN{a , TO2{Macaulay2Doc :: CompiledFunction, compiled function}}, .}}, HR{}, DIV{class => waystouse, PARA{The source of this document is in , TT{Macaulay2Doc/functions/deepSplice-doc.m2:49:0}, .}}}}

