{PRE{CODE{i7 : Lpairs = incompPolyhedra L

o7 = {(P1, P5), (P4, P5)}

o7 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i8 : Lpairs == {(P1,P4),(P1,P5)}

o8 = false, class => language-macaulay2}}}}}}, DIV{DIV{class => waystouse, HEADER2{Ways to use , TT{incompPolyhedra}, :}, UL{LI{KBD{incompPolyhedra(List)}}, LI{KBD{incompPolyhedra(PolyhedralComplex,PolyhedralComplex)}}, LI{KBD{incompPolyhedra(PolyhedralComplex,Polyhedron)}}, LI{KBD{incompPolyhedra(Polyhedron,PolyhedralComplex)}}}}, DIV{class => waystouse, HEADER2{For the programmer}, PARA{The object , TO{Polyhedra :: incompPolyhedra},  is , SPAN{a , TO2{Macaulay2Doc :: MethodFunction, method function}}, .}}, HR{}, DIV{class => waystouse, PARA{The source of this document is in , TT{Polyhedra/documentation/old_documentation.m2:1692:0}, .}}}}

