DIV{HEADER1{Print,  -- top level method for printing results}, UL{LI{DL{class => element, DT{Usage: }, DD{CODE{X#{topLevelMode,Print} = f, class => language-macaulay2}}}}, LI{Inputs:, UL{LI{SPAN{TT{X}, , , SPAN{a , TO2{Macaulay2Doc :: Type, type}}}}, LI{SPAN{TT{f}, , , SPAN{a , TO2{Macaulay2Doc :: Function, function}}, , ,  that can print something of type , TT{X}}}}}, LI{DIV{Consequences:, UL{LI{at top level, whenever it is time to print an output value of type , TT{X}, , the function , TT{f},  will be called}}}}}, DIV{HEADER2{Description}, The function , TT{f},  is responsible for printing the output prompt and for applying the , TO{Macaulay2Doc :: BeforePrint},  and , TO{Macaulay2Doc :: AfterPrint},  methods, if desired., TABLE{class => examples, TR{TD{PRE{CODE{i1 : code Thing#{Standard,Print}

o1 = /usr/share/Macaulay2/Core/robust.m2:133:25-
     149:6: --source code:
     Thing#{Standard,Print} = x -> (
          oprompt := concatenate(interpreterDepth:"o", toString lineNumber, " = ");
          save := printWidth;
          if printWidth != 0 then printWidth = printWidth - #oprompt;
          z := robustNet x;
          wrapper := lookup(global Wrap,class x);
          if wrapper =!= null then (
               fun := () -> z = wrapper z;
               try timelimit(printingTimeLimit, fun)
               else (
                    alarm 0;
                    global debugError <- fun;
                    stderr << "--error or time limit reached in applying Wrap method to output; type 'debugError()' to see it" << endl << endl);
               );
          << endl << oprompt << z << endl;
          printWidth = save;
          ), class => language-macaulay2}}}}}}, MENU{TO{Macaulay2Doc :: Wrap}}, DIV{DIV{class => waystouse, HEADER2{For the programmer}, PARA{The object , TO{Macaulay2Doc :: Print},  is , SPAN{a , TO2{Macaulay2Doc :: Symbol, symbol}}, .}}, HR{}, DIV{class => waystouse, PARA{The source of this document is in , TT{Macaulay2Doc/ov_repl.m2:315:0}, .}}}}

