remove.description:
DIV{HEADER1{remove,  -- remove an entry from a mutable hash table, list, or database}, UL{LI{DL{class => element, DT{Usage: }, DD{CODE{remove(T, k), class => language-macaulay2}}}}, LI{Inputs:, UL{LI{SPAN{TT{T}, , , SPAN{a , TO2{Macaulay2Doc :: HashTable, hash table}}, , , SPAN{a , TO2{Macaulay2Doc :: MutableList, mutable list}}, , or , SPAN{a , TO2{Macaulay2Doc :: Database, database}}, , }}, LI{SPAN{TT{k}, , , TEX{the key to remove (must be }, SPAN{an , TO2{Macaulay2Doc :: ZZ, integer}}, TEX{ if }, TT{T}, TEX{ is a mutable list or }, SPAN{a , TO2{Macaulay2Doc :: String, string}}, TEX{ if it is a database)}}}}}, LI{Outputs:, UL{LI{SPAN{SPAN{a , TO2{Macaulay2Doc :: Thing, thing}}, , , TEX{the removed value; }}}}}}, DIV{HEADER2{Description}, DIV{PARA{TEX{, TT{remove(T, k)},  removes and returns the entry of , TT{T},  stored under the key , TT{k}, .}}}, TABLE{class => examples, TR{TD{PRE{CODE{i1 : T = new MutableHashTable from {a => 1, b => 2, c => 3}; peek T

o2 = MutableHashTable{a => 1}
