o11 = 4, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i12 : peek T

o12 = MutableList{2, 3}, class => language-macaulay2}}}}}}, DIV{HEADER2{See also}, UL{LI{TOH{Macaulay2Doc :: applyKeys}}, LI{TOH{Macaulay2Doc :: applyPairs}}, LI{TOH{Macaulay2Doc :: applyValues}}, LI{TOH{Macaulay2Doc :: delete}}, LI{TOH{Macaulay2Doc :: drop}}, LI{TOH{Macaulay2Doc :: keys}}, LI{TOH{Macaulay2Doc :: isMutable}}, LI{TOH{Macaulay2Doc :: scanKeys}}, LI{TOH{Macaulay2Doc :: hash tables}}}}, DIV{DIV{class => waystouse, HEADER2{Ways to use , TT{remove}, :}, UL{LI{KBD{remove(Database,String)}}, LI{KBD{remove(HashTable,Thing)}}, LI{KBD{remove(MutableList,ZZ)}}}}, DIV{class => waystouse, HEADER2{For the programmer}, PARA{The object , TO{Macaulay2Doc :: remove},  is , SPAN{a , TO2{Macaulay2Doc :: CompiledFunction, compiled function}}, .}}, HR{}, DIV{class => waystouse, PARA{The source of this document is in , TT{Macaulay2Doc/ov_hashtables.m2:542:0}, .}}}}

