sublists.description:
DIV{HEADER1{sublists,  -- process interspersed subsequences of a visible list}, UL{LI{DL{class => element, DT{Usage: }, DD{CODE{sublists(L, f, g, h), class => language-macaulay2}}}}, LI{Inputs:, UL{LI{SPAN{TT{L}, , , SPAN{a , TO2{Macaulay2Doc :: VisibleList, visible list}}, , }}, LI{SPAN{TT{f}, , , SPAN{a , TO2{Macaulay2Doc :: Function, function}}, , , TEX{returning Boolean values}}}, LI{SPAN{TT{g}, , , SPAN{a , TO2{Macaulay2Doc :: Function, function}}, , , TEX{which acts on VisibleLists, applied to sublists of , TT{L},  with , TT{f(i)},  true for each , TT{i},  in the sublist}}}, LI{SPAN{TT{h}, , , SPAN{a , TO2{Macaulay2Doc :: Function, function}}, , , TEX{which acts on elements of , TT{L}, , applied to the elements , TT{i},  of , TT{L},  with , TT{f(i)},  false}}}}}, LI{Outputs:, UL{LI{SPAN{SPAN{a , TO2{Macaulay2Doc :: List, list}}, , , TEX{the result obtained by applying , TT{g},  to each of the maximal nonempty sequences of consecutive elements with , TT{f},  true, and applying , TT{h},  to the other elements}}}}}}, DIV{HEADER2{Description}, DIV{PARA{TEX{In the first example, consecutive odd elements are grouped into sublists, while each even element is negated.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i1 : L = {1,2,3,5,7,8,10,12,13,17,18,20,21};, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i2 : sublists(L, odd, toList, minus)

o2 = {{1}, -2, {3, 5, 7}, -8, -10, -12, {13, 17}, -18, -20, {21}}

o2 : List, class => language-macaulay2}}}}}, DIV{PARA{TEX{If , TT{g},  or , TT{h},  is omitted, the }, TO{Macaulay2Doc :: identity}, TEX{ function is used in its place.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i3 : sublists(L, odd, toList)

o3 = {{1}, 2, {3, 5, 7}, 8, 10, 12, {13, 17}, 18, 20, {21}}

o3 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i4 : sublists(L, odd)

o4 = {{1}, 2, {3, 5, 7}, 8, 10, 12, {13, 17}, 18, 20, {21}}

o4 : List, class => language-macaulay2}}}}}, DIV{PARA{TEX{The sublists will belong to the same class as , TT{L}, .}}}, TABLE{class => examples, TR{TD{PRE{CODE{i5 : L = (1,2,3,5,7,8,10,12,13,17,18,20,21);, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i6 : sublists(L, isPrime, , e -> 0)

o6 = {0, (2, 3, 5, 7), 0, 0, 0, (13, 17), 0, 0, 0}

o6 : List, class => language-macaulay2}}}}}, DIV{PARA{TEX{Note that , TT{g},  acts on the , EM{sublists}, , not their elements.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i7 : sublists(L, isPrime, plus, e -> 0)

o7 = {0, 17, 0, 0, 0, 30, 0, 0, 0}

o7 : List, class => language-macaulay2}}}}}, DIV{PARA{TEX{Because of the grouping of consecutive elements that return , TT{true},  when input to , TT{f}, , , TT{sublists(L, f, g, h)},  is NOT the same as applying , TT{g},  to elements returning , TT{true}, , and applying , TT{h},  to elements returning false. This could be achieved with a simple }, TO{Macaulay2Doc :: if}, TEX{-then-else loop, or with }, TO{Macaulay2Doc :: apply}, TEX{.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i8 : a = for l in L list if isPrime l then l else -10*l

o8 = {-10, 2, 3, 5, 7, -80, -100, -120, 13, 17, -180, -200, -210}

o8 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i9 : b = apply(L, l -> if isPrime l then l else -10*l)

o9 = (-10, 2, 3, 5, 7, -80, -100, -120, 13, 17, -180, -200, -210)

o9 : Sequence, class => language-macaulay2}}}}}, DIV{PARA{TEX{On the other hand, if we want to group both "true" and "false" elements into sublists, we can achieve this with a second call to , TT{sublists}, , selecting those elements not already grouped by the first , TT{sublists},  command, , EM{as long as the original list was not nested}, .}}}, TABLE{class => examples, TR{TD{PRE{CODE{i10 : X = {1, 3, 5, 2, 4, 7, 1, 3, 4, 4, 5, 4, 7, 9, 13};, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i11 : sublists(sublists(X, odd), i -> not instance(i, List))

o11 = {{1, 3, 5}, {2, 4}, {7, 1, 3}, {4, 4}, {5}, {4}, {7, 9, 13}}

o11 : List, class => language-macaulay2}}}}}}, DIV{HEADER2{See also}, UL{LI{TOH{Macaulay2Doc :: apply}}, LI{TOH{Macaulay2Doc :: partition}}, LI{TOH{Macaulay2Doc :: positions}}, LI{TOH{Macaulay2Doc :: select}}, LI{TOH{Macaulay2Doc :: lists and sequences}}}}, DIV{DIV{class => waystouse, HEADER2{Ways to use , TT{sublists}, :}, UL{LI{KBD{sublists(VisibleList,Function)}}, LI{KBD{sublists(VisibleList,Function,Function)}}, LI{KBD{sublists(VisibleList,Function,Function,Function)}}, LI{KBD{sublists(VisibleList,Function,Function,Nothing)}}, LI{KBD{sublists(VisibleList,Function,Nothing)}}, LI{KBD{sublists(VisibleList,Function,Nothing,Function)}}, LI{KBD{sublists(VisibleList,Function,Nothing,Nothing)}}}}, DIV{class => waystouse, HEADER2{For the programmer}, PARA{The object , TO{Macaulay2Doc :: sublists},  is , SPAN{a , TO2{Macaulay2Doc :: MethodFunction, method function}}, .}}, HR{}, DIV{class => waystouse, PARA{The source of this document is in , TT{Macaulay2Doc/functions/sublists-doc.m2:76:0}, .}}}}

subsets.description:
DIV{HEADER1{subsets,  -- produce the subsets of a set or list}, UL{LI{DL{class => element, DT{Usage: }, DD{CODE{subsets(A), class => language-macaulay2}}, DD{CODE{subsets(A, n), class => language-macaulay2}}}}, LI{Inputs:, UL{LI{SPAN{TT{A}, , , SPAN{a , TO2{Macaulay2Doc :: List, list}}, , , TEX{, sequence, set or integer}}}, LI{SPAN{TT{n}, , , SPAN{an , TO2{Macaulay2Doc :: ZZ, integer}}, , , TEX{optional input to specify subsets of a particular size}}}}}, LI{Outputs:, UL{LI{SPAN{TT{L}, , , SPAN{a , TO2{Macaulay2Doc :: List, list}}, , , TEX{of subsets (of size , TT{n},  if given)}}}}}}, DIV{HEADER2{Description}, DIV{PARA{TEX{If , TT{A},  is an integer, , TT{subsets(A)},  lists the subsets of , TT{\{0, 1, ..., A-1\}}, .}}}, TABLE{class => examples, TR{TD{PRE{CODE{i1 : subsets(3)

o1 = {{}, {0}, {1}, {0, 1}, {2}, {0, 2}, {1, 2}, {0, 1, 2}}

o1 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i2 : subsets(5, 3)

o2 = {{0, 1, 2}, {0, 1, 3}, {0, 2, 3}, {1, 2, 3}, {0, 1, 4}, {0, 2, 4}, {1,
     ------------------------------------------------------------------------
     2, 4}, {0, 3, 4}, {1, 3, 4}, {2, 3, 4}}

o2 : List, class => language-macaulay2}}}}}, DIV{PARA{TEX{, TT{A},  can be a list, sequence, or set. The elements need not be of the same type.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i3 : subsets({"apple", "banana", {1,2,3}, 7.1}, 3)

o3 = {{apple, banana, {1, 2, 3}}, {apple, banana, 7.1}, {apple, {1, 2, 3},
     ------------------------------------------------------------------------
     7.1}, {banana, {1, 2, 3}, 7.1}}

o3 : List, class => language-macaulay2}}}}}, DIV{PARA{TEX{If a list contains repetitions, so will the subsets of that list. Since a }, TO{Macaulay2Doc :: Set}, TEX{ has no repetitions, neither do its subsets. Also, the subsets of a set will again be sets (while the subsets of a list are lists).}}}, TABLE{class => examples, TR{TD{PRE{CODE{i4 : subsets({"apple", "apple", "banana"})

o4 = {{}, {apple}, {apple}, {apple, apple}, {banana}, {apple, banana},
