     {apple, banana}, {apple, apple, banana}}

o4 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i5 : subsets(set{"apple", "apple", "banana"})

o5 = {set {}, set {banana}, set {apple}, set {banana, apple}}

o5 : List, class => language-macaulay2}}}}}, DIV{PARA{TEX{The subsets of a Sequence are lists, not sequences. Also, a subset size , BOLD{must},  be specified when calling , TT{subsets},  on a sequence.}}}}, DIV{HEADER2{See also}, UL{LI{TOH{Macaulay2Doc :: partition}}, LI{TOH{Macaulay2Doc :: set}}, LI{TOH{Macaulay2Doc :: sublists}}, LI{TOH{Macaulay2Doc :: substring}}, LI{TOH{Macaulay2Doc :: lists and sequences}}}}, DIV{DIV{class => waystouse, HEADER2{Ways to use , TT{subsets}, :}, UL{LI{KBD{subsets(List)}}, LI{KBD{subsets(List,ZZ)}}, LI{KBD{subsets(Sequence,ZZ)}}, LI{KBD{subsets(Set)}}, LI{KBD{subsets(Set,ZZ)}}, LI{KBD{subsets(ZZ)}}, LI{KBD{subsets(ZZ,ZZ)}}}}, DIV{class => waystouse, HEADER2{For the programmer}, PARA{The object , TO{Macaulay2Doc :: subsets},  is , SPAN{a , TO2{Macaulay2Doc :: MethodFunction, method function}}, .}}, HR{}, DIV{class => waystouse, PARA{The source of this document is in , TT{Macaulay2Doc/functions/subsets-doc.m2:54:0}, .}}}}

