take.description:
DIV{HEADER1{take,  -- take some elements from a list or sequence}, UL{LI{DL{class => element, DT{Usage: }, DD{CODE{take(L, i), class => language-macaulay2}}, DD{CODE{take(L, {j,k}), class => language-macaulay2}}, DD{CODE{take(x, i), class => language-macaulay2}}}}, LI{Inputs:, UL{LI{SPAN{TT{L}, , , SPAN{a , TO2{Macaulay2Doc :: BasicList, basic list}}, , }}, LI{SPAN{TT{x}, , , SPAN{a , TO2{Macaulay2Doc :: Thing, thing}}, , }}, LI{SPAN{TT{i}, , , SPAN{an , TO2{Macaulay2Doc :: ZZ, integer}}, , }}, LI{SPAN{TT{j}, , , SPAN{an , TO2{Macaulay2Doc :: ZZ, integer}}, , }}, LI{SPAN{TT{k}, , , SPAN{an , TO2{Macaulay2Doc :: ZZ, integer}}, , }}}}, LI{Outputs:, UL{LI{SPAN{TT{L2}, , , SPAN{a , TO2{Macaulay2Doc :: BasicList, basic list}}, , , TEX{the list or sequence containing the first , TT{i},  elements of , TT{L}, , (if , TT{i},  positive), or the last , TT{i},  elements of , TT{L},  (if , TT{i},  negative), or, if given the pair , TT{j,k}, , the list or sequence containing the elements of , TT{L},  with indices , TT{j},  through , TT{k}, }}}}}}, DIV{HEADER2{Description}, TABLE{class => examples, TR{TD{PRE{CODE{i1 : take({a,b,c,d,e,f,g}, 3)

o1 = {a, b, c}

o1 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i2 : take({a,b,c,d,e,f,g}, -3)

o2 = {e, f, g}

o2 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i3 : take({a,b,c,d,e,f,g}, {1,3})

o3 = {b, c, d}

o3 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i4 : take({a,b,c,d,e,f,g}, {2,2})

o4 = {c}

o4 : List, class => language-macaulay2}}}}}, DIV{PARA{TEX{The pair $\{j,k\}$ must be given with both entries non-negative, and $j\le k$. Otherwise an empty list is returned.}}}, TABLE{class => examples, TR{TD{PRE{CODE{i5 : take({a,b,c,d,e,f,g}, {3,1})

o5 = {}

o5 : List, class => language-macaulay2}}}}, TR{TD{PRE{CODE{i6 : take({a,b,c,d,e,f,g}, {4,-1})

o6 = {}

